/**
 * auth.controller.js
 *
 * Transactional email for Firebase Auth (Brevo SMTP via mailer.js).
 * The recipient is ALWAYS the authenticated caller's own address — never one
 * taken from the request body — so this can't be used to spam or phish others.
 */

import { sendVerificationEmail } from '../services/mailer.js'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

/**
 * POST /api/auth/send-verification
 * Body: { token }  — UUID verification token generated by the client
 */
export async function sendVerification(req, res) {
  const { uid, email, emailVerified } = req.user
  const token = req.body?.token

  if (!email)         return res.status(400).json({ error: 'This account has no email address.' })
  if (emailVerified)  return res.status(409).json({ error: 'Email is already verified.' })
  if (typeof token !== 'string' || !UUID_RE.test(token)) {
    return res.status(400).json({ error: 'Invalid verification token format (expected UUID).' })
  }

  try {
    await sendVerificationEmail({ to: email, uid, token })
    return res.json({ success: true })
  } catch (err) {
    // Log details server-side; don't leak SMTP internals to the client
    console.error('[Auth Controller] Verification email failed:', err.message)
    return res.status(502).json({ error: 'Email delivery failed. Please try again later.' })
  }
}
